def is_topo(order, parents, root):
    if not isinstance(order, list) or len(order) != len(set(order)):
        return False
    need, stack = set(), [root]
    while stack:
        v = stack.pop()
        if v not in need:
            need.add(v)
            stack.extend(parents[v])
    if set(order) != need:
        return False
    pos = {v: i for i, v in enumerate(order)}
    return all(pos[p] < pos[v] for v in order for p in parents[v])

